# Re-auth and check CI via backend proxy + check S3 credentials status + check FFmpeg availability
cd /home/user/rork-app
bun -e '
// Re-auth
const loginRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
});
const loginData = await loginRes.json();
const token = loginData.accessToken;
if (!token) { console.log("AUTH FAILED"); process.exit(1); }
require("fs").writeFileSync("/tmp/owner_token.txt", token);
console.log("Auth OK, token saved");

// 1. Try to get CI status via backend proxy — check if it has GitHub Actions access
const ciRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_get_repo_head", confirm: true, confirmText: "", input: { branch: "main" } }),
});
const ciData = await ciRes.json();
console.log("=== GitHub HEAD ===");
console.log("headSha:", ciData.result?.headSha?.slice(0,12));
console.log("headCommitMessage:", ciData.result?.headCommitMessage?.slice(0,80));

// 2. Check production health for S3/AWS diagnostic info
const healthRes = await fetch("https://ivx-holdings-platform.onrender.com/health");
const healthData = await healthRes.json();
console.log("=== Production Health ===");
console.log("status:", healthData.status);
console.log("commit:", healthData.seniorDeveloperRuntime?.commitSha?.slice(0,12));
console.log("bootTime:", healthData.seniorDeveloperRuntime?.bootTime);

// 3. Try to query GitHub Actions runs directly via the backend proxy
// Check if there is a dedicated CI action
const actionsRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "developer_deploy_status", confirm: true, confirmText: "", input: {} }),
});
const actionsData = await actionsRes.json();
console.log("=== Developer Deploy Status ===");
console.log("githubHead:", actionsData.result?.githubHead?.headSha?.slice(0,12));
console.log("renderDeploy status:", actionsData.result?.renderDeploy?.status);
console.log("productionHealth commit:", actionsData.result?.productionHealth?.commit?.slice(0,12));
' 2>&1

