# Check if FFmpeg is available in this sandbox (for transcoding implementation)
which ffmpeg 2>/dev/null && ffmpeg -version 2>&1 | head -3 || echo "FFmpeg NOT available in sandbox"
echo "---"
# Check if FFmpeg is available on the backend
curl -sS https://ivx-holdings-platform.onrender.com/api/video/capabilities 2>/dev/null | bun -e '
try {
  const d = JSON.parse(await Bun.stdin.text());
  console.log("Backend video capabilities:");
  console.log("ffmpegAvailable:", d.ffmpegAvailable);
  console.log("videoUpload:", d.videoUpload);
  console.log("videoFrameExtraction:", d.videoFrameExtraction);
} catch(e) { console.log("Could not parse capabilities"); }
' 2>/dev/null

