cd /home/user/rork-app
APK_PATH="/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk"
echo "APK size: $(stat -c%s "$APK_PATH") bytes"
echo "APK SHA-256: $(sha256sum "$APK_PATH" | cut -d' ' -f1)"

# Re-auth + get presigned URL + upload APK atomically
bun -e '
const fs = require("fs");
const apkPath = "/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk";
const apkBytes = fs.readFileSync(apkPath);
console.log("APK size:", apkBytes.length, "bytes");

// Re-auth
const loginRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
});
const loginData = await loginRes.json();
const token = loginData.accessToken;
if (!token) { console.log("AUTH FAILED"); process.exit(1); }
require("fs").writeFileSync("/tmp/owner_token.txt", token);
console.log("Auth OK");

// Get presigned URL for APK upload to S3
const presignRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/apk/presign-upload", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ key: "apk/ivx-holdings-1.4.38.apk", confirmText: "CONFIRM_IVX_APK_UPLOAD" }),
});
const presignData = await presignRes.json();
console.log("Presign status:", presignRes.status);
console.log("Presign response:", JSON.stringify(presignData).slice(0, 300));

if (presignData.uploadUrl) {
  console.log("Got presigned URL, uploading APK...");
  const uploadRes = await fetch(presignData.uploadUrl, {
    method: "PUT",
    headers: { "Content-Type": "application/vnd.android.package-archive" },
