  } else {
    const uploadText = await uploadRes.text();
    console.log("Upload error:", uploadText.slice(0, 500));
  }
} else {
  console.log("No presign URL obtained. S3 may be unavailable.");
  console.log("Falling back to Supabase Storage...");
}
' 2>&1

