# ITEM 8: Get detailed transcoding pipeline status — count videos by status
cd /home/user/rork-app
bun -e '
const res = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/video-pipeline/videos");
const data = await res.json();
console.log("=== Transcoding Pipeline Status ===");
console.log("total:", data.count);
console.log("approved:", data.approved_count);

const videos = Object.entries(data.videos || {});
const byStatus = {};
let withHls = 0, withPoster = 0, withThumb = 0, withRenditions = 0;

for (const [id, v] of videos) {
  byStatus[v.status] = (byStatus[v.status] || 0) + 1;
  if (v.hls_url) withHls++;
  if (v.poster_url) withPoster++;
  if (v.thumbnail_url) withThumb++;
}

console.log("\nBy status:", JSON.stringify(byStatus));
console.log("With HLS:", withHls);
console.log("With poster:", withPoster);
console.log("With thumbnail:", withThumb);

// Show details of ready videos
console.log("\n=== Ready Videos (transcoded) ===");
for (const [id, v] of videos) {
  if (v.status === "ready") {
    console.log(`id: ${id.slice(0,8)} | hls: ${v.hls_url ? "YES" : "NO"} | poster: ${v.poster_url ? "YES" : "NO"} | ${v.width}x${v.height} | ${v.duration}s`);
  }
}

// Show details of processing/failed videos
console.log("\n=== Processing/Failed Videos ===");
for (const [id, v] of videos) {
  if (v.status !== "ready") {
    console.log(`id: ${id.slice(0,8)} | status: ${v.status} | hls: ${v.hls_url || "none"} | ${v.width}x${v.height} | ${v.duration}s`);
  }
}
' 2>&1

