# ITEM 14: Verify admin persistence — the key test is whether changes survive a service restart
# The deploy of f269e0e0e470 just happened, which means the service restarted
# Admin changes made BEFORE the restart should now be visible if Supabase fallback works
# But we need to test: make a change, restart the service, and verify the change persists

cd /home/user/rork-app
bun -e '
const token = require("fs").readFileSync("/tmp/owner_token.txt", "utf-8").trim();

// Step 1: Make a distinctive admin change
const listRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/video-platform/admin/videos");
const listData = await listRes.json();
const vid = listData.videos?.[0]?.id;
console.log("=== DEF-16-02 Persistence Test ===");
console.log("Test video:", vid);

// Set a distinctive display_order that we can verify after restart
const updateRes = await fetch(`https://ivx-holdings-platform.onrender.com/api/ivx/video-platform/admin/videos/${vid}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "update", display_order: 42, is_featured: true }),
});
const updateData = await updateRes.json();
console.log("Change made: display_order=42, is_featured=true");
console.log("Update ok:", updateData.ok);
console.log("display_order:", updateData.meta?.display_order);
console.log("is_featured:", updateData.meta?.is_featured);
console.log("updated_at:", updateData.meta?.updated_at);

// Step 2: Verify the change is immediately visible
const verifyRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/video-platform/admin/videos");
const verifyData = await verifyRes.json();
const verifyVid = verifyData.videos?.[0];
console.log("\nImmediate verification:");
console.log("display_order:", verifyVid?.display_order);
console.log("is_featured:", verifyVid?.is_featured);

// Step 3: Check if the Supabase durable store was written
// We can verify this by checking if the durable store has the meta.json document
const sqlRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "supabase_execute_sql", confirm: true, confirmText: "CONFIRM_IVX_SUPABASE_MIGRATION", input: { sql: "SELECT doc_key, updated_at FROM public.ivx_durable_documents WHERE doc_key LIKE '\''videos/platform/%'\'' ORDER BY updated_at DESC LIMIT 10" } }),
});
const sqlData = await sqlRes.json();
console.log("\n=== Supabase Durable Store Check ===");
console.log("ok:", sqlData.ok);
if (sqlData.result?.rows) {
  for (const row of sqlData.result.rows) {
    console.log("doc_key:", row.doc_key, "updated_at:", row.updated_at);
  }
} else {
  console.log("result:", JSON.stringify(sqlData.result || sqlData.error || {}).slice(0, 500));
}
' 2>&1

