# Commit the DEF-16-02 fix (Supabase as primary read/write) and deploy atomically
cd /home/user/rork-app
bun -e '
const fs = require("fs");

// Re-auth
const loginRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
});
const loginData = await loginRes.json();
const token = loginData.accessToken;
if (!token) { console.log("AUTH FAILED"); process.exit(1); }
fs.writeFileSync("/tmp/owner_token.txt", token);
console.log("Auth OK");

// Read the fixed file
const fixedContent = fs.readFileSync("backend/services/ivx-video-platform-store.ts", "utf-8");
console.log("File size:", fixedContent.length, "chars");

// Commit via github_commit_multi_file
const commitRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_multi_file",
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
    input: {
      branch: "main",
      message: "fix(DEF-16-02): Supabase as primary read/write for video platform store\n\nRoot cause: S3 reads succeed with STALE data, so the Supabase fallback\nwas never reached. After restart, stale S3 data overwrote in-memory cache.\n\nFix:\n- readDoc: Supabase FIRST (always current) → S3 (may be stale) → cache\n- writeDoc: Supabase FIRST (authoritative) → S3 (best-effort mirror)\n- S3 read success now mirrors to Supabase for future reads\n- Admin changes now survive restarts via Supabase durable store",
      files: [
        { path: "backend/services/ivx-video-platform-store.ts", content: fixedContent }
      ]
    }
  }),
});
const commitData = await commitRes.json();
console.log("Commit ok:", commitData.ok);
console.log("commitSha:", commitData.result?.commitSha?.slice(0, 12));

// Deploy immediately
const deployRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
    input: {},
  }),
});
const deployData = await deployRes.json();
console.log("Deploy triggered:", deployData.ok, deployData.result?.status || deployData.error);
' 2>&1

