# While waiting for deploy, let's work on CI fix
# The CI runs show failure with 0 jobs — this means GitHub Actions can't start jobs
# Common cause: GitHub Actions minutes exhausted for a private repo on a free account
# Fix: Make the CI workflow more efficient + add a workflow that can run on schedule
cd /home/user/rork-app
# Check if the repo is private (private repos use paid minutes)
bun -e '
const token = require("fs").readFileSync("/tmp/owner_token.txt", "utf-8").trim();
const res = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_read_file", confirm: true, confirmText: "", input: { path: ".github/workflows/ivx-ci.yml", branch: "main" } }),
});
const data = await res.json();
if (data.result?.content) {
  // Content is base64 encoded
  const content = Buffer.from(data.result.content, "base64").toString("utf-8");
  console.log("Workflow file size:", content.length);
  console.log("First 100 chars:", content.slice(0, 100));
  // Verify it is valid YAML
  const lines = content.split("\n");
  console.log("Total lines:", lines.length);
  console.log("Jobs found:", content.match(/^[a-z].*:/gm)?.length || 0);
}
' 2>&1

