    // Count renditions
    const renditions = hlsText.split("#EXT-X-STREAM-INF:").length - 1;
    console.log("  Rendition count:", renditions);
  }

  // Verify poster is accessible
  const posterRes = await fetch(v.poster_url, { method: "HEAD" });
  console.log("\nPoster image:");
  console.log("  HTTP status:", posterRes.status);
  console.log("  Content-Type:", posterRes.headers.get("content-type"));
  console.log("  Content-Length:", posterRes.headers.get("content-length"));
}

// Summary
console.log("\n=== Transcoding Pipeline Summary ===");
console.log("Total videos:", data.count);
const byStatus = {};
for (const [id, v] of videos) {
  byStatus[v.status] = (byStatus[v.status] || 0) + 1;
}
