console.log("Pipeline code: backend/services/ivx-video-pipeline.ts");
console.log("Worker: backend/services/ivx-video-worker.ts");

// Check the 2 processing videos
console.log("\n=== Processing Videos (stuck) ===");
for (const [id, v] of videos) {
  if (v.status === "processing") {
    console.log("Video:", id.slice(0,8), "updated:", v.updated_at);
    // Try retry
