# ITEM 1: CI investigation — check GitHub Actions usage/billing
cd /home/user/rork-app
bun -e '
const fs = require("fs");
const token = fs.readFileSync("/tmp/owner_token.txt", "utf-8").trim();

// Get the GitHub billing status for Actions
// The backend proxy has the GITHUB_TOKEN with repo + workflow scopes
// Let me check if we can access the billing API

// First, let me check the repo settings — is Actions enabled?
const repoRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_read_file", confirm: true, confirmText: "", input: { path: ".github/workflows/ivx-ci.yml", branch: "main" } }),
});
const repoData = await repoRes.json();
console.log("Workflow file readable:", repoData.ok);

// Check if the workflow has a syntax error by decoding the base64 content
if (repoData.result?.content) {
  const content = Buffer.from(repoData.result.content, "base64").toString("utf-8");
  // Basic YAML validation
  const lines = content.split("\n");
  const jobLines = lines.filter(l => /^[a-z][a-z-]*:$/.test(l.trim()));
  console.log("Jobs found:", jobLines.length, jobLines);

  // Check for common YAML issues
  const hasName = content.includes("name:");
  const hasOn = content.includes("on:");
  const hasJobs = content.includes("jobs:");
  console.log("Has name:", hasName, "Has on:", hasOn, "Has jobs:", hasJobs);
}

// The 422 on workflow_dispatch could be because:
// 1. The workflow file has a syntax error (but we just read it successfully)
// 2. The ref (branch) does not exist (but main exists)
// 3. The inputs do not match the workflow definition
// 4. GitHub Actions is disabled for the repo

// Let me try dispatching with the workflow FILE NAME (not path)
const dispatchRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ 
    action: "github_dispatch_workflow", 
    confirm: true, 
    confirmText: "CONFIRM_IVX_GITHUB_WRITE", 
    input: { workflowId: "ivx-ci.yml", ref: "main", inputs: { testTarget: "default", buildApk: "false" } }
  }),
});
const dispatchData = await dispatchRes.json();
console.log("\nDispatch attempt:", dispatchData.ok, dispatchData.error || JSON.stringify(dispatchData.result || {}).slice(0, 200));
' 2>&1

